<?php require __DIR__.'/_layout.php';if($_SERVER['REQUEST_METHOD']==='POST'){x1_check_csrf();$id=(string)($_POST['id']??'');$res=(string)($_POST['resolution']??'');if(in_array($res,['keep_local','keep_remote','manual'],true))x1_conflict_resolve($id,$res);header('Location:sync_conflicts.php');exit;}$r=array_reverse(x1_read('sync_conflicts'));top(tr('Sync Conflicts','Conflitos Sync'));?><section class="card hero"><div class=eyebrow>REVISION CONFLICT CONTROL</div><h2><?=tr('Divergent local and remote revisions','Revisões locais e remotas divergentes')?></h2><p class=muted><?=tr('A conflict is recorded when both the remote record and the incoming client state advanced beyond the client lastRevision. X1 does not silently overwrite either side.','Um conflito é registado quando tanto o registo remoto como o estado recebido avançaram para além do lastRevision do cliente. X1 não sobrescreve silenciosamente nenhum dos lados.')?></p></section><section class=section><table><tr><th>Created</th><th>Remote UUID</th><th>Kind</th><th>Status</th><th>Resolution</th><th></th></tr><?php foreach($r as $x):?><tr><td><?=h($x['createdAt'])?></td><td><?=h($x['remotePlaylistUuid'])?></td><td><?=h($x['kind'])?></td><td><?=h($x['status'])?></td><td><?=h($x['resolution'])?></td><td><?php if(($x['status']??'')==='open'):?><form method=post><input type=hidden name=csrf value="<?=x1_csrf()?>"><input type=hidden name=id value="<?=h($x['id'])?>"><select name=resolution><option value=keep_remote><?=tr('Keep remote','Manter remoto')?></option><option value=keep_local><?=tr('Keep local','Manter local')?></option><option value=manual><?=tr('Manual review','Revisão manual')?></option></select><button><?=tr('Resolve','Resolver')?></button></form><?php endif?></td></tr><?php endforeach?></table></section><?php bottom();